insert into public.listings (id, seller_id, status, title, description, category_id, tags, attributes, price_chf, negotiable, condition, comune_id, ai_source, published_at, sold_at, sold_price_chf) values
  ('l-001', (select id from auth.users where email = 'giulia@esempio.test'), 'pubblicato', 'Scrivania in noce massello, 120×60', 'Scrivania solida in noce massello con un cassetto. Qualche segno sul piano, nulla di rovinato. Smontabile per il trasporto.', 'arredamento', array['scrivania', 'noce', 'legno massello', 'ufficio']::text[], '{"materiale":"noce massello","misure":"120×60×75 cm"}'::jsonb, 140, false, 'buono', 'massagno', 'manuale', '2026-11-06T15:13:20.669Z', null, null),
  ('l-002', (select id from auth.users where email = 'paolo@esempio.test'), 'pubblicato', 'Scrivania vintage con 3 cassetti', 'Scrivania anni Settanta in abete, tre cassetti sul lato destro. Una maniglia è stata sostituita.', 'arredamento', array['scrivania', 'vintage', 'abete', 'cassetti']::text[], '{"materiale":"abete","misure":"110×55×76 cm"}'::jsonb, 95, false, 'usato', 'viganello', 'manuale', '2026-11-06T11:13:20.669Z', null, null),
  ('l-003', (select id from auth.users where email = 'davide@esempio.test'), 'pubblicato', 'Scrivania regolabile in rovere', 'Scrivania elettrica regolabile in altezza da 70 a 120 cm, piano in rovere. Usata un anno in smart working.', 'arredamento', array['scrivania', 'regolabile', 'rovere', 'elettrica', 'smart working']::text[], '{"materiale":"rovere","misure":"140×70 cm","altezza":"70–120 cm"}'::jsonb, 150, true, 'come_nuovo', 'canobbio', 'manuale', '2026-11-04T20:13:20.669Z', null, null),
  ('l-004', (select id from auth.users where email = 'sara@esempio.test'), 'pubblicato', 'Scrivania bianca laccata 140×70', 'Piano laccato bianco e gambe in metallo nero. Ottima per la cameretta.', 'arredamento', array['scrivania', 'bianca', 'metallo', 'cameretta']::text[], '{"materiale":"laccato e metallo","misure":"140×70 cm"}'::jsonb, 60, false, 'buono', 'lugano', 'manuale', '2026-11-03T20:13:20.669Z', null, null),
  ('l-005', (select id from auth.users where email = 'elena@esempio.test'), 'pubblicato', 'Scrivania in faggio per cameretta', 'Scrivania compatta in faggio con mensola. Qualche adesivo da togliere.', 'arredamento', array['scrivania', 'faggio', 'cameretta', 'bambini']::text[], '{"materiale":"faggio","misure":"100×50 cm"}'::jsonb, 70, false, 'buono', 'agno', 'manuale', '2026-11-01T20:13:20.669Z', null, null),
  ('l-006', (select id from auth.users where email = 'nicola@esempio.test'), 'pubblicato', 'Scrivania in pino con alzata', 'Scrivania in pino naturale con alzata porta libri. Da ritirare al primo piano, senza ascensore.', 'arredamento', array['scrivania', 'pino', 'legno', 'alzata']::text[], '{"materiale":"pino","misure":"120×60 cm"}'::jsonb, 120, false, 'buono', 'locarno', 'manuale', '2026-11-05T20:13:20.669Z', null, null),
  ('l-007', (select id from auth.users where email = 'francesca@esempio.test'), 'pubblicato', 'Scrivania da architetto in teak, anni 60', 'Pezzo di design scandinavo in teak, piano inclinabile. Restaurata da un falegname nel 2024.', 'arredamento', array['scrivania', 'teak', 'design', 'vintage', 'anni 60']::text[], '{"materiale":"teak","anno":"1965"}'::jsonb, 380, false, 'buono', 'paradiso', 'manuale', '2026-11-02T20:13:20.669Z', null, null),
  ('l-008', (select id from auth.users where email = 'marco@esempio.test'), 'pubblicato', 'Tavolo da pranzo allungabile in rovere', 'Tavolo allungabile da 160 a 220 cm, sei posti comodi. Le sedie non sono incluse.', 'arredamento', array['tavolo', 'pranzo', 'rovere', 'allungabile']::text[], '{"materiale":"rovere","misure":"160–220×90 cm"}'::jsonb, 450, false, 'buono', 'bellinzona', 'manuale', '2026-10-31T20:13:20.669Z', null, null),
  ('l-009', (select id from auth.users where email = 'chiara@esempio.test'), 'pubblicato', 'Libreria in rovere a 5 ripiani', 'Libreria alta 190 cm, ripiani regolabili. Va fissata al muro.', 'arredamento', array['libreria', 'rovere', 'scaffale']::text[], '{"materiale":"rovere","misure":"80×30×190 cm"}'::jsonb, 90, false, 'buono', 'minusio', 'manuale', '2026-10-30T20:13:20.669Z', null, null),
  ('l-010', (select id from auth.users where email = 'laura@esempio.test'), 'pubblicato', 'Divano 3 posti grigio, sfoderabile', 'Divano tre posti in tessuto grigio, fodere lavate di recente. Animali in casa: nessuno.', 'arredamento', array['divano', 'tre posti', 'grigio', 'sfoderabile']::text[], '{"misure":"210×90 cm"}'::jsonb, 250, false, 'buono', 'giubiasco', 'manuale', '2026-10-29T20:13:20.669Z', null, null),
  ('l-011', (select id from auth.users where email = 'roberto@esempio.test'), 'pubblicato', 'Poltrona Liberty in velluto verde', 'Poltrona in stile Liberty, struttura in legno sana, velluto verde con qualche segno sui braccioli.', 'arredamento', array['poltrona', 'liberty', 'velluto', 'vintage', 'antiquariato']::text[], '{"materiale":"legno e velluto"}'::jsonb, 280, false, 'buono', 'mendrisio', 'manuale', '2026-10-28T20:13:20.669Z', null, null),
  ('l-012', (select id from auth.users where email = 'anna@esempio.test'), 'venduto', 'Scrivania in noce 140×70', 'Scrivania in noce con due cassetti.', 'arredamento', array['scrivania', 'noce', 'legno']::text[], '{"materiale":"noce","misure":"140×70 cm"}'::jsonb, 180, false, 'buono', 'lugano', 'manuale', '2026-09-27T20:13:20.669Z', '2026-09-27T20:13:20.669Z', 160),
  ('l-013', (select id from auth.users where email = 'simone@esempio.test'), 'venduto', 'Scrivania in rovere chiaro', 'Scrivania semplice in rovere chiaro, gambe in legno.', 'arredamento', array['scrivania', 'rovere', 'legno']::text[], '{"materiale":"rovere","misure":"120×60 cm"}'::jsonb, 140, false, 'buono', 'savosa', 'manuale', '2026-10-02T20:13:20.669Z', '2026-10-02T20:13:20.669Z', 130),
  ('l-014', (select id from auth.users where email = 'marta@esempio.test'), 'pubblicato', 'Bici da corsa Bianchi Via Nirone 7, telaio 55', 'Telaio in alluminio, gruppo Shimano Sora. Graffi leggeri sul telaio, gomme cambiate in primavera.', 'bici', array['bici da corsa', 'bianchi', 'alluminio', 'shimano', 'strada']::text[], '{"taglia":"55","materiale":"alluminio"}'::jsonb, 450, true, 'buono', 'bellinzona', 'manuale', '2026-11-05T17:13:20.669Z', null, null),
  ('l-015', (select id from auth.users where email = 'matteo@esempio.test'), 'pubblicato', 'Bici da corsa Cube Attain, taglia 56', 'Usata per una stagione, sempre in garage. Freni a disco idraulici.', 'bici', array['bici da corsa', 'cube', 'freni a disco', 'strada']::text[], '{"taglia":"56","materiale":"alluminio"}'::jsonb, 520, false, 'come_nuovo', 'locarno', 'manuale', '2026-11-02T20:13:20.669Z', null, null),
  ('l-016', (select id from auth.users where email = 'ilaria@esempio.test'), 'pubblicato', 'Bici da corsa Specialized Allez, taglia 54', 'Bici da allenamento, segni d’uso evidenti ma meccanica a posto. Pedali non inclusi.', 'bici', array['bici da corsa', 'specialized', 'strada']::text[], '{"taglia":"54","materiale":"alluminio"}'::jsonb, 390, false, 'usato', 'lugano', 'manuale', '2026-10-27T20:13:20.669Z', null, null),
  ('l-017', (select id from auth.users where email = 'fabio@esempio.test'), 'venduto', 'Bici da corsa Bianchi Via Nirone, telaio 57', 'Bici da corsa in alluminio, ben tenuta.', 'bici', array['bici da corsa', 'bianchi', 'strada']::text[], '{"taglia":"57"}'::jsonb, 460, false, 'buono', 'biasca', 'manuale', '2026-09-07T20:13:20.669Z', '2026-09-07T20:13:20.669Z', 430),
  ('l-018', (select id from auth.users where email = 'luca@esempio.test'), 'venduto', 'Bici da corsa Giant Contend, taglia 56', 'Bici da corsa entry level, revisionata.', 'bici', array['bici da corsa', 'giant', 'strada']::text[], '{"taglia":"56"}'::jsonb, 500, false, 'buono', 'mendrisio', 'manuale', '2026-09-17T20:13:20.669Z', '2026-09-17T20:13:20.669Z', 480),
  ('l-019', (select id from auth.users where email = 'elena@esempio.test'), 'pubblicato', 'E-bike trekking Flyer Upstreet, batteria nuova', 'E-bike svizzera da città e gite, batteria sostituita a marzo. Portapacchi e luci integrate.', 'bici', array['ebike', 'bici elettrica', 'flyer', 'trekking', 'pedalata assistita']::text[], '{"taglia":"M","batteria":"625 Wh"}'::jsonb, 1450, false, 'buono', 'locarno', 'manuale', '2026-11-06T00:13:20.669Z', null, null),
  ('l-020', (select id from auth.users where email = 'sara@esempio.test'), 'pubblicato', 'Bici bambina 20 pollici, rosa con cestino', 'Bici per bambina dai 6 agli 8 anni, cambio a 6 velocità. Cestino e campanello inclusi.', 'bici', array['bici', 'bambina', 'bambini', '20 pollici']::text[], '{"ruote":"20\""}'::jsonb, 90, false, 'buono', 'bellinzona', 'manuale', '2026-11-04T16:13:20.669Z', null, null),
  ('l-021', (select id from auth.users where email = 'andrea@esempio.test'), 'pubblicato', 'Bici bambino 16 pollici con rotelle', 'Prima bici con rotelle smontabili, adatta dai 4 ai 6 anni.', 'bici', array['bici', 'bambino', 'bambini', '16 pollici', 'rotelle']::text[], '{"ruote":"16\""}'::jsonb, 60, false, 'buono', 'arbedo-castione', 'manuale', '2026-11-01T20:13:20.669Z', null, null),
