  ('l-023', (select id from auth.users where email = 'nicola@esempio.test'), 'pubblicato', 'Mountain bike Scott Scale 29, taglia L', 'Front in alluminio, forcella revisionata. Segni d’uso sul carro posteriore.', 'bici', array['mountain bike', 'mtb', 'scott', '29 pollici']::text[], '{"taglia":"L","ruote":"29\""}'::jsonb, 650, false, 'usato', 'faido', 'manuale', '2026-10-26T20:13:20.669Z', null, null),
  ('l-024', (select id from auth.users where email = 'fabio@esempio.test'), 'pubblicato', 'Sci Atomic Redster 170 cm con attacchi', 'Sci da pista, lamine affilate a novembre. Attacchi regolati per scarpone 27.5.', 'sport_inverno', array['sci', 'atomic', 'pista', 'attacchi']::text[], '{"lunghezza":"170 cm"}'::jsonb, 180, false, 'buono', 'airolo', 'manuale', '2026-11-05T14:13:20.669Z', null, null),
  ('l-025', (select id from auth.users where email = 'matteo@esempio.test'), 'pubblicato', 'Scarponi da sci Lange, 27.5', 'Usati cinque giorni, come nuovi. Flex 100.', 'sport_inverno', array['scarponi', 'sci', 'lange']::text[], '{"taglia":"27.5"}'::jsonb, 120, false, 'come_nuovo', 'locarno', 'manuale', '2026-11-03T20:13:20.669Z', null, null),
